#include <Arduino.h>
#include <TM1637Display.h>

TM1637Display display(4, 5);
unsigned int count = 0;
unsigned long tickAt = 0;
unsigned long changedAt = 0;
int lastRaw = HIGH;
int stableButton = HIGH;

void showCount() {
  display.showNumberDec(count, false);
}

void setup() {
  pinMode(2, INPUT_PULLUP);
  display.setBrightness(7);
  showCount();
  tickAt = millis();
  changedAt = millis();
}

void loop() {
  unsigned long now = millis();
  int raw = digitalRead(2);
  if (raw != lastRaw) {
    lastRaw = raw;
    changedAt = now;
  }
  if (raw != stableButton && now - changedAt >= 25UL) {
    stableButton = raw;
    if (stableButton == LOW) {
      count = 0;
      tickAt = now;
      showCount();
    }
  }
  while (now - tickAt >= 1000UL) {
    tickAt += 1000UL;
    count = (count + 1) % 10000;
    showCount();
  }
}
